mapper.update:
UPDATE agent_schedule_execution
SET tenant_id = #{tenantId}, user_id = #{userId}, task_id = #{taskId}, execution_id = #{executionId}, trace_id = #{traceId}, start_time = #{startTime}, end_time = #{endTime}, duration_ms = #{durationMs}, status = #{status}, error_message = #{errorMessage}, metadata = #{metadata}
WHERE id = #{id} AND deleted = 0

UPDATE agent_schedule_execution
SET status = #{status}, end_time = #{endTime}, duration_ms = #{durationMs},
    error_message = #{errorMessage}, result_json = #{resultJson}
WHERE execution_id = #{executionId} AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken} AND status = 'running' AND deleted = 0

mapper.select:
SELECT execution.*
FROM agent_schedule_execution execution
INNER JOIN agent_schedule_config config ON config.config_id = execution.config_id
WHERE execution.tenant_id <=> #{tenantId} AND execution.user_id = #{userId}
  AND execution.config_id = #{configId} AND config.owner_user_id = #{userId}
  AND execution.deleted = 0 AND config.deleted = 0
ORDER BY execution.planned_time DESC, execution.id DESC
LIMIT #{limit}
